#include <iostream>
#include <stdexcept>

class Time {
public:
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    void setTime(int h, int m, int s) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60 && s >= 0 && s < 60) {
            hour = static_cast<unsigned int>(h);
            minute = static_cast<unsigned int>(m);
            second = static_cast<unsigned int>(s);
        } else {
            throw std::invalid_argument("Time out of range");
        }
    }

    unsigned int getHour() const {
        return hour;
    }

    // Dangerous: returns a non-const reference to private data
    unsigned int& badSetHour(int h) {
        if (h >= 0 && h < 24) {
            hour = static_cast<unsigned int>(h);
        } else {
            throw std::invalid_argument("hour must be 0-23");
        }
        return hour;
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t;

    // 1. Alias binding allows invalid direct mutation
    unsigned int& hourRef = t.badSetHour(20);
    std::cout << "Valid hour before modification: " << hourRef << '\n';

    hourRef = 30; // Corrupts private state
    std::cout << "Invalid hour after modification: " << t.getHour() << '\n';

    // 2. Invoking function as modifiable lvalue directly
    t.badSetHour(12) = 74; // Corrupts private state
    std::cout << "Hour after lvalue call assignment: " << t.getHour() << '\n';

    return 0;
}

#include <iostream>

class Date {
public:
    // Explicit constructor with default arguments
    explicit Date(unsigned int m = 1, unsigned int d = 1, unsigned int y = 2000)
        : month{m}, day{d}, year{y} {}

    void print() const {
        std::cout << month << '/' << day << '/' << year;
    }

private:
    unsigned int month{1};
    unsigned int day{1};
    unsigned int year{2000};
};

int main() {
    Date date1{7, 4, 2004};
    Date date2; // Defaults to 1/1/2000

    std::cout << "date1 = ";
    date1.print();
    std::cout << "\ndate2 = ";
    date2.print();

    // Default memberwise assignment
    date2 = date1;

    std::cout << "\n\nAfter default memberwise assignment, date2 = ";
    date2.print();
    std::cout << '\n';

    return 0;
}
